// Current original-form owner replies, fictional PostgreSQL; no prompt is sent.
async fn queue_question_fixture()->(PgConnection,Value,Value,automated_apply_agents::private_resume::Settings){
    let(mut c,work,resumes)=questionnaire_fixture().await;let mut waiting=questionnaire_observe(&mut c,&work,questionnaire_report(&work,"What is your full name?"),&resumes).await.unwrap();waiting["stage"]=json!("NEEDS_INPUT");waiting["status"]=json!("waiting");waiting["reason"]=json!("questionnaire_verified_answer_required");waiting["revision"]=json!(waiting["revision"].as_i64().unwrap()+1);let id=waiting["id"].as_str().unwrap().parse::<Uuid>().unwrap();browser_save(&mut c,&format!("apply_work:{id}"),waiting.clone()).await;let question=automated_apply_agents::execution::owner_questions::ask(&mut c,id,&packet_settings(),&resumes).await.unwrap();(c,waiting,question,resumes)
}
async fn queue_owner_answer(c:&mut PgConnection,q:&Value,text:&str,resumes:&automated_apply_agents::private_resume::Settings)->Result<Value>{automated_apply_agents::execution::owner_questions::answer_dashboard(c,q["id"].as_str().unwrap().parse().unwrap(),q["packet_revision"].as_i64().unwrap(),text,&packet_settings(),resumes).await}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_question_is_deduplicated_and_dashboard_answer_requires_account_resume_job_form_refresh(){
    let(mut c,work,q,resumes)=queue_question_fixture().await;let again=automated_apply_agents::execution::owner_questions::ask(&mut c,work["id"].as_str().unwrap().parse().unwrap(),&packet_settings(),&resumes).await.unwrap();assert_eq!(again,q);assert_eq!(q["reuse_approved"],false);let name:String=sqlx::query_scalar("SELECT full_name FROM candidate_profiles WHERE singleton_key='primary'").fetch_one(&mut c).await.unwrap();let answered=queue_owner_answer(&mut c,&q,&name,&resumes).await.unwrap();assert_eq!(answered["state"],"answered");assert_eq!(answered["provenance"]["source"],"owner_dashboard");assert_eq!(answered["reuse_approved"],false);let current=browser_pref(&mut c,&format!("apply_work:{}",work["id"].as_str().unwrap())).await;assert_eq!(current["operation"],"refresh_questionnaire_profile");assert_eq!(current["status"],"queued");assert_eq!(current["admitted_actions"],work["admitted_actions"]);assert_eq!(current["questionnaire_answer"]["question_id"],q["id"]);assert!(current["permit_expires_at"].is_null());assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'aa_ans:')").fetch_one(&mut c).await.unwrap(),0);assert_eq!(queue_owner_answer(&mut c,&q,&name,&resumes).await.unwrap_err(),Failure("question_already_answered"));
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_question_reply_rejects_wrong_revision_expiry_stop_and_changed_step_without_mutation(){
    let(mut c,work,q,resumes)=queue_question_fixture().await;let key=format!("exec_q:{}",q["id"].as_str().unwrap());let work_key=format!("apply_work:{}",work["id"].as_str().unwrap());let config=browser_pref(&mut c,"application_queue_policy").await;
    for kind in ["revision","expired","stop","step"]{browser_save(&mut c,&key,q.clone()).await;browser_save(&mut c,&work_key,work.clone()).await;browser_save(&mut c,"application_queue_policy",config.clone()).await;let mut request=q.clone();match kind{"revision"=>request["packet_revision"]=json!(q["packet_revision"].as_i64().unwrap()+1),"expired"=>{let mut expired=q.clone();expired["expires_at"]=json!("2000-01-01T00:00:00Z");browser_save(&mut c,&key,expired).await;},"stop"=>{let mut stopped=config.clone();stopped["state"]=json!("STOPPED");browser_save(&mut c,"application_queue_policy",stopped).await;},_=>{let mut changed=work.clone();changed["questionnaire"]["step_sha256"]=json!("f".repeat(64));browser_save(&mut c,&work_key,changed).await;}}let before=browser_snapshot(&mut c).await;assert!(queue_owner_answer(&mut c,&request,"Verified Fictional Name",&resumes).await.is_err());assert_eq!(browser_snapshot(&mut c).await,before);}
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_question_reuse_requires_separate_owner_action_and_keeps_all_hash_bits(){
    let(mut c,_work,q,resumes)=queue_question_fixture().await;let approved=automated_apply_agents::execution::owner_questions::approve_reuse(&mut c,q["id"].as_str().unwrap().parse().unwrap(),&packet_settings()).await.unwrap_err();assert_eq!(approved,Failure("current_answer_required"));let answered=queue_owner_answer(&mut c,&q,"Verified Fictional Name",&resumes).await.unwrap();let approved=automated_apply_agents::execution::owner_questions::approve_reuse(&mut c,q["id"].as_str().unwrap().parse().unwrap(),&packet_settings()).await.unwrap();assert_eq!(approved["reuse_approved"],true);let key=approved["reuse_key"].as_str().unwrap();assert_eq!(key.len(),50);let bank=browser_pref(&mut c,key).await;assert_eq!(bank["answer"],answered["answer"]);assert_eq!(bank["question_id"],q["id"]);assert_eq!(bank["answer_expires_at"],answered["answer_expires_at"]);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_question_dropped_answer_or_event_ack_cannot_resume_work_or_save_a_partial_reply(){
    let(mut c,_work,q,resumes)=queue_question_fixture().await;let before=browser_snapshot(&mut c).await;
    for operation in ["question","event"]{if operation=="question"{sqlx::raw_sql("CREATE FUNCTION fixture_reply_drop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF starts_with(NEW.key,'exec_q:') THEN RETURN NULL; END IF; RETURN NEW; END $$;CREATE TRIGGER fixture_reply_drop BEFORE UPDATE ON owner_preferences FOR EACH ROW EXECUTE FUNCTION fixture_reply_drop()").execute(&mut c).await.unwrap();}else{sqlx::raw_sql("CREATE FUNCTION fixture_reply_drop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF starts_with(NEW.key,'apply_event:') THEN RETURN NULL; END IF; RETURN NEW; END $$;CREATE TRIGGER fixture_reply_drop BEFORE INSERT ON owner_preferences FOR EACH ROW EXECUTE FUNCTION fixture_reply_drop()").execute(&mut c).await.unwrap();}assert_eq!(queue_owner_answer(&mut c,&q,"Verified Fictional Name",&resumes).await.unwrap_err(),Failure("execution_write_ack_failed"));assert_eq!(browser_snapshot(&mut c).await,before);sqlx::raw_sql("DROP TRIGGER fixture_reply_drop ON owner_preferences;DROP FUNCTION fixture_reply_drop()").execute(&mut c).await.unwrap();}
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_question_expired_existing_prompt_and_message_ids_are_retained_without_reenrollment(){
    let(mut c,work,q,resumes)=queue_question_fixture().await;let mut expired=q.clone();expired["expires_at"]=json!("2000-01-01T00:00:00Z");expired["state"]=json!("sent");expired["message_ids"]=json!([1234]);expired["expired_message_ids"]=json!([1233]);browser_save(&mut c,&format!("exec_q:{}",q["id"].as_str().unwrap()),expired.clone()).await;let again=automated_apply_agents::execution::owner_questions::ask(&mut c,work["id"].as_str().unwrap().parse().unwrap(),&packet_settings(),&resumes).await.unwrap();assert_eq!(again,expired);assert_eq!(queue_owner_answer(&mut c,&q,"Verified Fictional Name",&resumes).await.unwrap_err(),Failure("question_expired_or_application_cancelled"));
}
